    bronze_castingladlenozzle = { name = "Bronast šobe za zajemalke", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast šobe za zajemalke za livarje." },
