function CastingLadleNozzleMaker.init() CastingLadleNozzleMaker.ironStock=18; CastingLadleNozzleMaker.bronzeStock=14; CastingLadleNozzleMaker.woodStock=10; CastingLadleNozzleMaker.leatherStock=8; CastingLadleNozzleMaker.silverStock=8; CastingLadleNozzleMaker.goldStock=6; CastingLadleNozzleMaker.jewelStock=4; CastingLadleNozzleMaker.pearlStock=4; CastingLadleNozzleMaker.productStock={}; CastingLadleNozzleMaker.buildings={}; CastingLadleNozzleMaker.maker=nil; CastingLadleNozzleMaker.activeMaking={}; CastingLadleNozzleMaker.totalProducts=0; CastingLadleNozzleMaker.dayTimer=0; print("[CastingLadleNozzleMaker] Royal Casting Ladle Nozzle Maker System initialized (6 products, 4 buildings)") end
function CastingLadleNozzleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CastingLadleNozzleMaker.maker={name=n or ("Šobnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šobnik najet: %s (spretnost: %d)",CastingLadleNozzleMaker.maker.name,s),"success") end; return true end
function CastingLadleNozzleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CastingLadleNozzleMaker.build(id) local ok,e=CastingLadleNozzleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CastingLadleNozzleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CastingLadleNozzleMaker.getQualityBonus() local b=0; for _,bd in ipairs(CastingLadleNozzleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CastingLadleNozzleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CastingLadleNozzleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CastingLadleNozzleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CastingLadleNozzleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CastingLadleNozzleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CastingLadleNozzleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CastingLadleNozzleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CastingLadleNozzleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CastingLadleNozzleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CastingLadleNozzleMaker.buildings==0 then return false,"Potrebna šobna delavnica" end; if not CastingLadleNozzleMaker.maker then return false,"Potreben sobnik" end; return true end
function CastingLadleNozzleMaker.make(pt,qty) qty=qty or 1; local ok,e=CastingLadleNozzleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CastingLadleNozzleMaker.ironStock=CastingLadleNozzleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CastingLadleNozzleMaker.bronzeStock=CastingLadleNozzleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CastingLadleNozzleMaker.woodStock=CastingLadleNozzleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CastingLadleNozzleMaker.leatherStock=CastingLadleNozzleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CastingLadleNozzleMaker.silverStock=CastingLadleNozzleMaker.silverStock-d.silverCost*qty end; if d.goldCost then CastingLadleNozzleMaker.goldStock=CastingLadleNozzleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CastingLadleNozzleMaker.jewelStock=CastingLadleNozzleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CastingLadleNozzleMaker.pearlStock=CastingLadleNozzleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CastingLadleNozzleMaker.maker then t=math.max(1,t-math.floor(CastingLadleNozzleMaker.maker.skill/13)) end; table.insert(CastingLadleNozzleMaker.activeMaking,{id="castingladlenozzle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CastingLadleNozzleMaker.completeMaking(m) local q=1.0+(CastingLadleNozzleMaker.getQualityBonus()/100); if CastingLadleNozzleMaker.maker then q=q+(CastingLadleNozzleMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadleNozzleMaker.productStock[m.productType]=(CastingLadleNozzleMaker.productStock[m.productType] or 0)+m.quantity; CastingLadleNozzleMaker.totalProducts=CastingLadleNozzleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadleNozzleMaker.maker then CastingLadleNozzleMaker.maker.itemsMade=CastingLadleNozzleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadleNozzleMaker.maker.skill=math.min(100,CastingLadleNozzleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šoba izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladlenozzle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CastingLadleNozzleMaker.update(dt) if not _G.state then return end; CastingLadleNozzleMaker.dayTimer=CastingLadleNozzleMaker.dayTimer+dt; if CastingLadleNozzleMaker.dayTimer>=30 then CastingLadleNozzleMaker.dayTimer=0; for i=#CastingLadleNozzleMaker.activeMaking,1,-1 do local m=CastingLadleNozzleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CastingLadleNozzleMaker.completeMaking(m); table.remove(CastingLadleNozzleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CastingLadleNozzleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CastingLadleNozzleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CastingLadleNozzleMaker.getStats() return {ironStock=CastingLadleNozzleMaker.ironStock,bronzeStock=CastingLadleNozzleMaker.bronzeStock,woodStock=CastingLadleNozzleMaker.woodStock,leatherStock=CastingLadleNozzleMaker.leatherStock,silverStock=CastingLadleNozzleMaker.silverStock,goldStock=CastingLadleNozzleMaker.goldStock,jewelStock=CastingLadleNozzleMaker.jewelStock,pearlStock=CastingLadleNozzleMaker.pearlStock,productStock=CastingLadleNozzleMaker.productStock,numBuildings=#CastingLadleNozzleMaker.buildings,hasMaker=CastingLadleNozzleMaker.maker~=nil,makerName=CastingLadleNozzleMaker.maker and CastingLadleNozzleMaker.maker.name or "—",makerSkill=CastingLadleNozzleMaker.maker and CastingLadleNozzleMaker.maker.skill or 0,activeMaking=#CastingLadleNozzleMaker.activeMaking,totalProducts=CastingLadleNozzleMaker.totalProducts} end
